-- 34 bảng nghiệp vụ theo báo cáo; tên cột được ánh xạ sang English cho ứng dụng.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS nguoi_dung (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT UNIQUE, phone TEXT UNIQUE, password_hash TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, verified INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT, CHECK(email IS NOT NULL OR phone IS NOT NULL));
CREATE TABLE IF NOT EXISTS khach_hang (id INTEGER PRIMARY KEY REFERENCES nguoi_dung(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS nhan_vien (id INTEGER PRIMARY KEY REFERENCES nguoi_dung(id) ON DELETE CASCADE, job_title TEXT NOT NULL DEFAULT 'sales' CHECK(job_title IN ('pharmacist','sales','warehouse')));
CREATE TABLE IF NOT EXISTS quan_tri_vien (id INTEGER PRIMARY KEY REFERENCES nguoi_dung(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS vai_tro (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS nguoi_dung_vai_tro (user_id INTEGER NOT NULL REFERENCES nguoi_dung(id) ON DELETE CASCADE, role_id INTEGER NOT NULL REFERENCES vai_tro(id), PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS quyen (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quyen_vai_tro (role_id INTEGER NOT NULL REFERENCES vai_tro(id), permission_id INTEGER NOT NULL REFERENCES quyen(id), PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS phan_quyen (user_id INTEGER NOT NULL REFERENCES nguoi_dung(id) ON DELETE CASCADE, permission_id INTEGER NOT NULL REFERENCES quyen(id), allowed INTEGER NOT NULL, PRIMARY KEY(user_id,permission_id));
CREATE TABLE IF NOT EXISTS ma_otp (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES nguoi_dung(id) ON DELETE CASCADE, code_hash TEXT NOT NULL, purpose TEXT NOT NULL, expires_at TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, consumed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS nhat_ky_hoat_dong (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER REFERENCES nguoi_dung(id), action TEXT NOT NULL, entity TEXT, entity_id TEXT, detail TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS danh_muc (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, slug TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS nha_san_xuat (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, country TEXT NOT NULL DEFAULT 'Việt Nam', active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS thuoc (id INTEGER PRIMARY KEY AUTOINCREMENT, category_id INTEGER NOT NULL REFERENCES danh_muc(id), manufacturer_id INTEGER REFERENCES nha_san_xuat(id), name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, ingredient TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', usage TEXT NOT NULL DEFAULT '', warning TEXT NOT NULL DEFAULT '', unit TEXT NOT NULL, price INTEGER NOT NULL CHECK(price>=0), old_price INTEGER, image TEXT NOT NULL DEFAULT '', prescription_required INTEGER NOT NULL DEFAULT 0, featured INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT);
CREATE TABLE IF NOT EXISTS dia_chi_giao_hang (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES nguoi_dung(id) ON DELETE CASCADE, recipient TEXT NOT NULL, phone TEXT NOT NULL, line1 TEXT NOT NULL, ward TEXT NOT NULL DEFAULT '', district TEXT NOT NULL DEFAULT '', city TEXT NOT NULL, is_default INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS gio_hang (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL UNIQUE REFERENCES nguoi_dung(id) ON DELETE CASCADE, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS chi_tiet_gio_hang (id INTEGER PRIMARY KEY AUTOINCREMENT, cart_id INTEGER NOT NULL REFERENCES gio_hang(id) ON DELETE CASCADE, product_id INTEGER NOT NULL REFERENCES thuoc(id), quantity INTEGER NOT NULL CHECK(quantity>0), UNIQUE(cart_id,product_id));
CREATE TABLE IF NOT EXISTS khuyen_mai (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('percent','fixed')), value INTEGER NOT NULL CHECK(value>0), min_order INTEGER NOT NULL DEFAULT 0, max_discount INTEGER, usage_limit INTEGER NOT NULL DEFAULT 100, used_count INTEGER NOT NULL DEFAULT 0, start_date TEXT NOT NULL, end_date TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS don_hang (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES nguoi_dung(id), code TEXT NOT NULL UNIQUE, status TEXT NOT NULL, payment_method TEXT NOT NULL, payment_status TEXT NOT NULL DEFAULT 'unpaid', subtotal INTEGER NOT NULL, shipping_fee INTEGER NOT NULL, discount INTEGER NOT NULL DEFAULT 0, total INTEGER NOT NULL CHECK(total>=0), address_json TEXT NOT NULL, promotion_id INTEGER REFERENCES khuyen_mai(id), note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT, stock_deducted INTEGER NOT NULL DEFAULT 0, stock_released INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS chi_tiet_don_hang (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL REFERENCES don_hang(id), product_id INTEGER NOT NULL REFERENCES thuoc(id), name TEXT NOT NULL, unit TEXT NOT NULL, image TEXT NOT NULL, price INTEGER NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), prescription_required INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS don_thuoc (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES nguoi_dung(id), order_id INTEGER UNIQUE REFERENCES don_hang(id), file_name TEXT NOT NULL, storage_name TEXT NOT NULL, mime_type TEXT NOT NULL, size INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', note TEXT NOT NULL DEFAULT '', approved_product_ids TEXT, reviewer_id INTEGER REFERENCES nguoi_dung(id), reviewed_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS giao_dich_thanh_toan (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL REFERENCES don_hang(id), reference TEXT NOT NULL UNIQUE, type TEXT NOT NULL, provider TEXT NOT NULL, amount INTEGER NOT NULL, status TEXT NOT NULL, provider_reference TEXT, expires_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS yeu_cau_huy_hoan (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL REFERENCES don_hang(id), user_id INTEGER NOT NULL REFERENCES nguoi_dung(id), type TEXT NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', reply TEXT NOT NULL DEFAULT '', refund_amount INTEGER, restock INTEGER NOT NULL DEFAULT 0, evidence_storage_name TEXT, evidence_mime_type TEXT, handler_id INTEGER REFERENCES nguoi_dung(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT);
CREATE TABLE IF NOT EXISTS hang_tra_ve (id INTEGER PRIMARY KEY AUTOINCREMENT, request_id INTEGER NOT NULL UNIQUE REFERENCES yeu_cau_huy_hoan(id), order_id INTEGER NOT NULL REFERENCES don_hang(id), status TEXT NOT NULL DEFAULT 'awaiting' CHECK(status IN ('awaiting','in_transit','received','restocked','discarded')), carrier TEXT NOT NULL DEFAULT '', tracking_code TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', handler_id INTEGER REFERENCES nguoi_dung(id), received_at TEXT, inspected_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT);
CREATE TABLE IF NOT EXISTS danh_gia (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL REFERENCES don_hang(id), product_id INTEGER NOT NULL REFERENCES thuoc(id), user_id INTEGER NOT NULL REFERENCES nguoi_dung(id), rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), comment TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(order_id,product_id,user_id));
CREATE TABLE IF NOT EXISTS nha_cung_cap (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS phieu_nhap_kho (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, supplier_id INTEGER REFERENCES nha_cung_cap(id), user_id INTEGER NOT NULL REFERENCES nguoi_dung(id), total INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS lo_thuoc (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL REFERENCES thuoc(id), receipt_id INTEGER REFERENCES phieu_nhap_kho(id), batch_number TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>=0), reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=quantity), cost INTEGER NOT NULL DEFAULT 0 CHECK(cost>=0), manufactured_at TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(product_id,batch_number));
CREATE TABLE IF NOT EXISTS lich_su_ton_kho (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL REFERENCES thuoc(id), batch_id INTEGER NOT NULL REFERENCES lo_thuoc(id), order_id INTEGER REFERENCES don_hang(id), user_id INTEGER REFERENCES nguoi_dung(id), type TEXT NOT NULL, quantity INTEGER NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cuoc_hoi_thoai (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES nguoi_dung(id), title TEXT NOT NULL DEFAULT 'Cuộc trò chuyện mới', status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tin_nhan (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER NOT NULL REFERENCES cuoc_hoi_thoai(id) ON DELETE CASCADE, role TEXT NOT NULL, content TEXT NOT NULL, mode TEXT NOT NULL DEFAULT 'knowledge', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS yeu_cau_ho_tro (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER NOT NULL REFERENCES cuoc_hoi_thoai(id), user_id INTEGER NOT NULL REFERENCES nguoi_dung(id), message TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending', reply TEXT NOT NULL DEFAULT '', handler_id INTEGER REFERENCES nguoi_dung(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT);
CREATE TABLE IF NOT EXISTS tri_thuc_chatbot (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, keywords TEXT NOT NULL, content TEXT NOT NULL, source TEXT, reviewed_at TEXT, reviewed_by INTEGER REFERENCES nguoi_dung(id), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quy_tac_an_toan (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, pattern TEXT NOT NULL, response TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS tu_khoa_canh_bao (id INTEGER PRIMARY KEY AUTOINCREMENT, rule_id INTEGER NOT NULL REFERENCES quy_tac_an_toan(id), keyword TEXT NOT NULL);
-- Các bảng kỹ thuật lưu phiên, cấu hình, giữ chỗ tồn kho, lịch sử và liên kết Google.
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES nguoi_dung(id) ON DELETE CASCADE, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stock_allocations (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL REFERENCES don_hang(id), batch_id INTEGER NOT NULL REFERENCES lo_thuoc(id), quantity INTEGER NOT NULL CHECK(quantity>0), UNIQUE(order_id,batch_id));
CREATE TABLE IF NOT EXISTS order_status_history (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL REFERENCES don_hang(id), status TEXT NOT NULL, user_id INTEGER REFERENCES nguoi_dung(id), note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS google_accounts (subject TEXT PRIMARY KEY, user_id INTEGER NOT NULL UNIQUE REFERENCES nguoi_dung(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS oauth_states (state_hash TEXT PRIMARY KEY, nonce TEXT NOT NULL, verifier TEXT NOT NULL, user_id INTEGER REFERENCES nguoi_dung(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_order_user ON don_hang(user_id,created_at);
CREATE INDEX IF NOT EXISTS idx_batch_expiry ON lo_thuoc(product_id,expires_at);
CREATE INDEX IF NOT EXISTS idx_message_session ON tin_nhan(session_id,id);
CREATE INDEX IF NOT EXISTS idx_otp_user ON ma_otp(user_id,purpose,id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_single_refund ON giao_dich_thanh_toan(order_id) WHERE type='refund' AND status IN ('pending','success');
